hl.curve("linear",         { type = "bezier", points = { {2, 0},       {1, 1}       } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.65, 0.15},   {0.75, 1}    } })
hl.curve("quick",          { type = "bezier", points = { {1.00, 0},    {0.1, 1}     } })
-- Default springs
