hl.bind(mainMod .. " + T", hl.dsp.exec_cmd("current=$(hyprctl getoption general:layout -j | jq -r '.str'); if [ \"$current\" = \"scrolling\" ]; then hyprctl keyword general:layout dwindle; else hyprctl keyword general:layout scrolling; fi"))


local currentLayout = "scrolling"

local function toggleLayout()
    if currentLayout == "scrolling" then
        currentLayout = "dwindle"
    else
        currentLayout = "scrolling"
    end

    hl.set_config("general:layout", currentLayout)
end

hl.bind(mainMod .. " + T", toggleLayout)

local layouts = { "dwindle", "scrolling", "master" }

hl.bind("SUPER + G", function()
    local current = hl.get_config("general.layout")
    local idx = 1
    for i, name in ipairs(layouts) do
        if name == current then idx = i break end
    end
    local new = layouts[(idx % #layouts) + 1]
    hl.config({ general = { layout = new } })
    hl.notification.create({ text = "Layout: " .. new, timeout = 500 })
end)


hl.bind("SUPER + SHIFT + X", function()
    if hl.get_workspace("special:minimized") then
        -- رجّع النافذة
        hl.dispatch(hl.dsp.window.move({ workspace = hl.get_active_workspace(), window = "tag:minimized" }))
        hl.dispatch(hl.dsp.window.clear_tags({ window = "tag:minimized" }))
    else
        -- خبّي النافذة
        hl.dispatch(hl.dsp.window.tag({ tag = "minimized", window = hl.get_active_window() }))
        hl.dispatch(hl.dsp.window.move({ workspace = "special:minimized", follow = false }))
    end
end)

